const fieldsArray = $input.first().json.value;

return fieldsArray.map(f => ({
  id: f.Id,
  name: f.Name,
  key: f.Key,
  typeId: f.TypeId,
  optionsTableId: f.OptionsTableId || null,
  entityId: f.EntityId  // 👈 aqui você já sabe se é contato (1) ou deal (2)
}));

const deals = $input.first().json.value;

const stages = new Map();

for (const d of deals) {
  const st = d.Stage;
  if (st && st.Id) {
    stages.set(st.Id, {
      stageId: st.Id,
      stageName: st.Name,
      pipelineId: st.PipelineId
    });
  }
}

return Array.from(stages.values()).map(s => ({ json: s }));

// n8n Code node (JavaScript)
// Compara profundamente dois valores (objetos/arrays/primitivos) e retorna mudanças.
// Saída no formato de items do n8n: [{ json: { changes, added, removed, onlyChangedNewValues, hasChanges } }]

/** Testa igualdade profunda segura (obj, array, primitivo, null/undefined) */
function isDeepEqual(a, b) {
  if (a === b) return true;

  // Trata NaN
  if (typeof a === 'number' && typeof b === 'number' && isNaN(a) && isNaN(b)) return true;

  // Tipos diferentes
  if (typeof a !== typeof b) return false;

  // Nulls
  if (a == null || b == null) return a === b;

  // Datas
  if (a instanceof Date || b instanceof Date) {
    const da = a instanceof Date ? a : new Date(a);
    const db = b instanceof Date ? b : new Date(b);
    return da.getTime() === db.getTime();
  }

  // Buffers/TypedArrays (tratados como string)
  if ((typeof Buffer !== 'undefined' && Buffer.isBuffer?.(a)) || (typeof Buffer !== 'undefined' && Buffer.isBuffer?.(b))) {
    return String(a) === String(b);
  }

  // Arrays
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!isDeepEqual(a[i], b[i])) return false;
    }
    return true;
  }
  if (Array.isArray(a) || Array.isArray(b)) return false;

  // Objetos
  if (typeof a === 'object' && typeof b === 'object') {
    const ka = Object.keys(a);
    const kb = Object.keys(b);
    if (ka.length !== kb.length) return false;
    for (const k of ka) {
      if (!Object.prototype.hasOwnProperty.call(b, k)) return false;
      if (!isDeepEqual(a[k], b[k])) return false;
    }
    return true;
  }

  // Primitivos
  return a === b;
}

/** Gera uma string de caminho legível (ex.: "OtherProperties.deal_...") */
function joinPath(pathArr) {
  return pathArr
    .map(seg => (typeof seg === 'number' ? `[${seg}]` : (pathArr.length && typeof seg === 'string' && seg.includes('.') ? `["${seg}"]` : String(seg))))
    .reduce((acc, seg, idx) => {
      if (seg.startsWith('[')) return acc + seg;
      return idx === 0 ? seg : acc + '.' + seg;
    }, '');
}

/**
 * Diff recursivo entre dois valores
 * - changes: [{ path, oldValue, newValue, changeType: 'changed'|'added'|'removed' }]
 * - added:   [{ path, newValue }]
 * - removed: [{ path, oldValue }]
 */
function deepDiff(oldVal, newVal, path = [], out = { changes: [], added: [], removed: [] }) {
  // Igual — não registra
  if (isDeepEqual(oldVal, newVal)) return out;

  // Se tipos mudaram ou virou primitivo, é mudança direta
  const oldIsObj = oldVal && typeof oldVal === 'object';
  const newIsObj = newVal && typeof newVal === 'object';
  const oldIsArr = Array.isArray(oldVal);
  const newIsArr = Array.isArray(newVal);

  // Caso geral: um lado não-objeto/array => mudança direta
  if ((!oldIsObj && !newIsObj) || oldIsArr !== newIsArr || (oldIsObj && !newIsObj) || (!oldIsObj && newIsObj)) {
    out.changes.push({ path: joinPath(path), oldValue: oldVal, newValue: newVal, changeType: 'changed' });
    return out;
  }

  // Arrays: compara por índice (genérico)
  if (oldIsArr && newIsArr) {
    const maxLen = Math.max(oldVal.length, newVal.length);
    for (let i = 0; i < maxLen; i++) {
      if (i >= oldVal.length) {
        // added
        out.added.push({ path: joinPath([...path, i]), newValue: newVal[i] });
        out.changes.push({ path: joinPath([...path, i]), oldValue: undefined, newValue: newVal[i], changeType: 'added' });
      } else if (i >= newVal.length) {
        // removed
        out.removed.push({ path: joinPath([...path, i]), oldValue: oldVal[i] });
        out.changes.push({ path: joinPath([...path, i]), oldValue: oldVal[i], newValue: undefined, changeType: 'removed' });
      } else {
        // recursivo
        deepDiff(oldVal[i], newVal[i], [...path, i], out);
      }
    }
    return out;
  }

  // Objetos: percorre chaves de ambos
  const oldKeys = Object.keys(oldVal);
  const newKeys = Object.keys(newVal);
  const allKeys = new Set([...oldKeys, ...newKeys]);

  for (const key of allKeys) {
    const inOld = Object.prototype.hasOwnProperty.call(oldVal, key);
    const inNew = Object.prototype.hasOwnProperty.call(newVal, key);

    if (inOld && !inNew) {
      out.removed.push({ path: joinPath([...path, key]), oldValue: oldVal[key] });
      out.changes.push({ path: joinPath([...path, key]), oldValue: oldVal[key], newValue: undefined, changeType: 'removed' });
    } else if (!inOld && inNew) {
      out.added.push({ path: joinPath([...path, key]), newValue: newVal[key] });
      out.changes.push({ path: joinPath([...path, key]), oldValue: undefined, newValue: newVal[key], changeType: 'added' });
    } else {
      // Existe nos dois — comparar recursivamente
      deepDiff(oldVal[key], newVal[key], [...path, key], out);
    }
  }

  return out;
}

/** Constrói um objeto { path: newValue } apenas para campos alterados/novos (útil para PATCH) */
function buildOnlyChangedNewValues(changesArr) {
  const out = {};
  for (const ch of changesArr) {
    // Ignora removidos (newValue === undefined)
    if (typeof ch.newValue === 'undefined') continue;
    out[ch.path] = ch.newValue;
  }
  return out;
}

// ========= CAPTURA "Old" e "New" =========
const payload = $input.first().json.body; // seu exemplo
const oldObj = payload?.Old ?? {};
const newObj = payload?.New ?? {};

// ========= DIFF =========
const diff = deepDiff(oldObj, newObj);
const onlyChangedNewValues = buildOnlyChangedNewValues(diff.changes);

// ========= RESULTADO PARA PRÓXIMOS NÓS =========
return [
  {
    json: {
      changes: diff.changes,           // [{ path, oldValue, newValue, changeType }]
      added: diff.added,               // [{ path, newValue }]
      removed: diff.removed,           // [{ path, oldValue }]
      onlyChangedNewValues,            // { "StageId": 0 /* SEU_ID_AQUI */, "UpdaterId": 0 /* SEU_ID_AQUI */, "LastUpdateDate": "2025-08-22T01:33:41.91", ... }
      hasChanges: diff.changes.length > 0
    }
  }
];

function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

// Retorna o UUID no campo "id"
return [
  {
    json: {
      id: generateUUID()
    }
  }
];

