// Número original vindo do Edit Fields
let numeroOriginal = $input.first().json.mobile_phone || "";

// Remove todos os caracteres que não sejam dígitos
let numeroLimpo = numeroOriginal.replace(/\D/g, "");

// Validação: precisa ter entre 10 e 13 dígitos
if (numeroLimpo.length < 10 || numeroLimpo.length > 13) {
  return [
    {
      json: {
        TelefoneCorrigido: "",
        TelefoneUltimos8: ""
      }
    }
  ];
}

// Se tiver 10 ou 11 dígitos, adiciona o código do Brasil (55) na frente
if (numeroLimpo.length === 10 || numeroLimpo.length === 11) {
  numeroLimpo = "55" + numeroLimpo;
}

// Pega os últimos 8 dígitos
const telefoneUltimos8 = numeroLimpo.slice(-8);

// Retorno no formato esperado
return [
  {
    json: {
      TelefoneCorrigido: numeroLimpo,
      TelefoneUltimos8: telefoneUltimos8
    }
  }
];

