// items: [{ json: { extras: { Fila: "Comercial" } } }, ...]

// 1) Collect, clean, and deduplicate
const uniques = [...new Set(
  items
    .map(i => i?.json?.extras?.Fila)
    .filter(v => v != null)                   // remove null/undefined
    .map(v => String(v).trim())               // trim spaces
    .filter(v => v !== "")                    // remove empty
)];

// 2) Return as array of items: [{ json: { Fila: "..." } }, ...]
return uniques.map(v => ({ json: { Fila: v } }));

